#include <cstddef>
#include <cstdint>
#include <cstring>
#include <cmath>
static void putd(std::uint8_t*o,std::size_t p,double x){std::uint64_t b;std::memcpy(&b,&x,8);for(int k=0;k<8;k++)o[p+k]=std::uint8_t(b>>(8*k));}
extern "C" std::int64_t ordinary_least_squares_regressor(const std::int64_t*v,std::size_t n,std::uint8_t*out,std::size_t cap){if(!v||n<6)return -1;int nr=int(v[0]),f=int(v[1]),t=int(v[2]);if(nr<2||nr>8||f!=2||t<1||t>3||n!=3+std::size_t(nr)*3+std::size_t(t)*2)return -1;double a[3][3]={},b[3]={};std::size_t p=3;for(int r=0;r<nr;r++){auto x=v[p],y=v[p+1],zv=v[p+2];p+=3;if(x < -100||x>100||y < -100||y>100||zv < -1000||zv>1000)return -1;double z[3]={double(x),double(y),1};for(int i=0;i<3;i++){b[i]+=z[i]*zv;for(int j=0;j<3;j++)a[i][j]+=z[i]*z[j];}}for(int c=0;c<3;c++){int pivot=c;for(int r=c+1;r<3;r++)if(std::abs(a[r][c])>std::abs(a[pivot][c]))pivot=r;if(std::abs(a[pivot][c])<1e-12)return -1;for(int j=0;j<3;j++){double q=a[c][j];a[c][j]=a[pivot][j];a[pivot][j]=q;}double q=b[c];b[c]=b[pivot];b[pivot]=q;double scale=a[c][c];for(int j=c;j<3;j++)a[c][j]/=scale;b[c]/=scale;for(int r=0;r<3;r++)if(r!=c){double k=a[r][c];for(int j=c;j<3;j++)a[r][j]-=k*a[c][j];b[r]-=k*b[c];}}if(!out||cap<std::size_t(t)*8)return -2;for(int r=0;r<t;r++){double y=0;for(int j=0;j<2;j++){auto x=v[p++];if(x < -100||x>100)return -1;y+=double(x)*b[j];}putd(out,std::size_t(r)*8,y+b[2]);}return std::int64_t(t)*8;}
